import i18n from 'i18next';
const MAIL_LANGUAGES = ['en', 'uk'];
// Мова, якою показано сайт, для листа з кодом входу. Невідома мова —
// undefined: поле не надсилається, і бекенд бере мову браузера або англійську.
export const siteLanguage = (language = i18n.resolvedLanguage) => MAIL_LANGUAGES.find((supported) => supported === language);
